#!/usr/bin/env python3
# Writes generated/ltc.c3, the linearly transformed cosines' tables RectAreaLight needs, from
# three.js's examples/jsm/lights/RectAreaLightTexturesLib.js (MIT, three.js authors), whose
# numbers are the fit of Heitz, Dupuy, Hill and Neubelt, "Real-Time Polygonal-Light Shading
# with Linearly Transformed Cosines", 2016 (github.com/selfshadow/ltc_code, fit/results/ltc.js).
#   python3 third_party/ltc/ltc.py driejs/vendor/jsm/lights/RectAreaLightTexturesLib.js generated/ltc.c3
import re, sys

src = open(sys.argv[1]).read()
tables = {}
for name in ("LTC_MAT_1", "LTC_MAT_2"):
    m = re.search(r"const " + name + r" = \[([^\]]*)\]", src)
    values = [float(x.replace(" ", "")) for x in m.group(1).split(",") if x.strip()]
    assert len(values) == 64 * 64 * 4, (name, len(values))
    tables[name] = values

def fmt(x):
    s = repr(float(x))
    return s if ("e" in s or "." in s) else s + ".0"

with open(sys.argv[2], "w") as out:
    out.write("// Generated by third_party/ltc/ltc.py from three.js r187's RectAreaLightTexturesLib.js\n")
    out.write("// (MIT, three.js authors): the linearly transformed cosines of Heitz, Dupuy, Hill and\n")
    out.write("// Neubelt, \"Real-Time Polygonal-Light Shading with Linearly Transformed Cosines\", 2016\n")
    out.write("// (github.com/selfshadow/ltc_code). 64 x 64 texels of 4 floats, by roughness across and\n")
    out.write("// sqrt(1 - cos(theta)) down, as three's LTC_FLOAT_1 and LTC_FLOAT_2. Do not edit.\n")
    out.write("module drie;\n\n")
    for name, c3name in (("LTC_MAT_1", "LTC_1"), ("LTC_MAT_2", "LTC_2")):
        v = tables[name]
        out.write("const float[%d] %s @private = {\n" % (len(v), c3name))
        for i in range(0, len(v), 8):
            out.write("    " + ", ".join(fmt(x) for x in v[i:i + 8]) + ",\n")
        out.write("};\n\n")
